def url_join(base, url, allow_fragments=True):
    """Join a base URL and a possibly relative URL to form an absolute
    interpretation of the latter.

    :param base: the base URL for the join operation.
    :param url: the URL to join.
    :param allow_fragments: indicates weather fragments should be allowed.
    """
    if isinstance(base, tuple):
        base = url_unparse(base)
    if isinstance(url, tuple):
        url = url_unparse(url)

    base, url = normalize_string_tuple((base, url))
    s = make_literal_wrapper(base)

    if not base:
        return url
    if not url:
        return base

    bscheme, bnetloc, bpath, bquery, bfragment = \
        url_parse(base, allow_fragments=allow_fragments)
    scheme, netloc, path, query, fragment = \
        url_parse(url, bscheme, allow_fragments)
    if scheme != bscheme:
        return url
    if netloc:
        return url_unparse((scheme, netloc, path, query, fragment))
    netloc = bnetloc

    if path[:1] == s('/'):
        return url_unparse((scheme, netloc, path, query, fragment))

    if not path:
        path = bpath
        if not query:
            query = bquery
        return url_unparse((scheme, netloc, path, query, fragment))
    segments = bpath.split(s('/'))[:-1] + path.split(s('/'))
    # XXX The stuff below is bogus in various ways...
    if segments[-1] == s('.'):
        segments[-1] = s('')
    segments = [segment for segment in segments if segment != s('.')]
    while 1:
        i = 1
        n = len(segments) - 1
        while i < n:
            if (segments[i] == s('..')
                and segments[i - 1] not in (s(''), s('..'))):
                del segments[i - 1:i + 1]
                break
            i += 1
        else:
            break
    if segments == [s(''), s('..')]:
        segments[-1] = s('')
    elif len(segments) >= 2 and segments[-1] == s('..'):
        segments[-2:] = [s('')]
    return url_unparse((scheme, netloc, s('/').join(segments), query, fragment))
